function renderBarrelList(){renderEditableBarrels()}
function renderBarrelListLegacy(){const rows=barrelConfiguration();if(!Number.isInteger(state.selectedBarrel)||state.selectedBarrel>=rows.length)state.selectedBarrel=-1;$("#barrelStatus").textContent=`${rows.length} positions · ${rows.at(-1).mm} mm`;$("#barrelPortBtn").disabled=!rows[state.selectedBarrel]?.portKey;$("#barrelCloseBtn").disabled=!rows[state.selectedBarrel]?.portKey;$("#barrelList").innerHTML=rows.map((row,i)=>`<div class="barrel-row barrel-${row.role} ${i===state.selectedBarrel?'selected':''}" data-index="${i}" title="${row.portKey?'双击切换 ATM / CLOSED':'标准固定配置'}"><span class="barrel-mini">${machinePartSVG(row.name)}</span><span>${row.pos}</span><span>${row.mm}</span><span>${esc(row.name)}</span><span class="barrel-annotation ${row.portKey?'editable':''}">${row.annotation}</span></div>`).join('');$$('.barrel-row').forEach(row=>{row.onclick=()=>{state.selectedBarrel=+row.dataset.index;renderBarrelList()};row.ondblclick=()=>toggleBarrelPort(+row.dataset.index)})}
function renderDrawing(){const wrap=$('#drawingWrap'),oldScroll=wrap.scrollLeft,sameMachine=wrap.dataset.viewportMachine===state.machine;wrap.innerHTML=desktopDrawingSVG();$("#drawingTitle").textContent=state.metadata.drawing_name||"新建螺杆组合";$("#drawingSub").textContent=`${spec().name} · ${state.metadata.material||""}`;$("#machinePaneName").textContent=spec().name;$("#barrelLD").textContent=`机筒工艺长度：${BarrelModels.summary(state.machine,spec(),state.ports).process_d}D / ${BarrelModels.summary(state.machine,spec(),state.ports).sections}节（标准节4D）`;$("#screwLD").textContent=`方案螺杆目标：${BarrelModels.targetLength(state.machine,spec(),state.ports)} mm`;applyDrawingZoom();if(sameMachine&&state.sequence.length)wrap.scrollLeft=oldScroll;bindDrawingInteractions();WorkspaceUI.refresh()}
function renderDesign(){collectMeta();state.ports=ports();renderSequence();renderDrawing();renderBarrelList();renderValidation();showSelected();setStatus()}
function renderAll(){renderTypes();renderLibrary();renderDesign();renderProjects();renderComponentsPage();renderInventory();renderSettings()}
function renderTypes(){const labels={GFA:'GFA 输送',GFF:'GFF 输送',KB:'KB 剪切',GFM:'GFM 混合',KS:'KS 端部',Spacer:'间隔套'},types=[...new Set(comps().map(c=>libraryGroup(c.type)))];$("#typeFilter").innerHTML='<option value="">全部类型</option>'+types.map(x=>`<option value="${x}">${labels[x]||x}</option>`).join('')}
function openModal(title,content,actions=[]){FluentDrag.cancel();$("#modalTitle").textContent=title;$("#modalContent").innerHTML=`<div class="modal-content">${content}</div>`;$("#modalActions").innerHTML="";actions.forEach(a=>{const b=document.createElement("button");b.textContent=a.label;b.className=a.primary?"primary":"";b.onclick=a.click;$("#modalActions").append(b)});$("#modal").classList.remove("hidden")}
function closeModal(){$("#modal").classList.add("hidden")}
function approval(message){return new Promise(resolve=>openModal("负责人确认",`<div class="warn-box">${message}</div><div class="modal-form" style="margin-top:12px"><label class="wide">强制放行原因<textarea id="approvalReason" rows="3" required></textarea></label><label class="wide">负责人确认码<input id="approvalCode" type="password" placeholder="电话号码，尾号0731"></label></div>`,[{label:"取消",click:()=>{closeModal();resolve(null)}},{label:"确认放行",primary:true,click:async()=>{const reason=$("#approvalReason").value.trim(),code=$("#approvalCode").value;if(!reason||!code){toast("请填写原因和确认码",true);return}const x=await api('/api/verify-code',{method:'POST',body:{code}});if(!x.ok){toast("负责人确认码错误",true);return}closeModal();resolve({reason,code})}}]))}
function cleanMetadata(){const out={};for(const k of ['drawing_name','machine_no','version','date','author','material','comments','side1_label','side2_label'])if(state.metadata[k]!=null)out[k]=state.metadata[k];return out}
async function saveProject(asNew=false){collectMeta();state.metadata=cleanMetadata();const v=calculate();let app=null;if(v.difference||v.violations.length||v.barrel_warnings.length){app=await approval(`当前组合长度差值 ${v.difference} mm，安全冲突 ${v.violations.length} 处。${esc(v.barrel_warnings.join('；'))}`);if(!app)return}const editingState=state,editingID=state.id,payload={id:asNew?null:state.id,machine:state.machine,metadata:{...state.metadata},sequence:[...state.sequence],ports:JSON.parse(JSON.stringify(state.ports)),override_reason:app?.reason||"",confirm_code:app?.code||""};try{const x=await api('/api/projects',{method:'POST',body:payload});toast("螺杆与机筒方案已保存，可从“打开方案”恢复");if(state===editingState&&state.id===editingID){state.id=x.id;state.status="draft";setStatus();WorkspaceUI.markClean(payload)}await reloadData();}catch(e){toast(e.message,true)}}
async function reloadData(){const x=await api('/api/bootstrap');DATA={...DATA,...x}}
function renderProjects(){const body=$("#projectsBody");if(!body)return;body.innerHTML=DATA.projects.map(p=>{const m=p.metadata||{},st={draft:["草稿","warn"],released:["已发布","ok"],void:["已作废","bad"]}[p.status]||[p.status,""];return `<tr><td><b>${esc(p.name)}</b></td><td>${esc(DATA.machines[p.machine]?.name)}</td><td>${esc(m.version||"")}</td><td>${esc(m.material||"")}</td><td><span class="badge ${st[1]}">${st[0]}</span></td><td>${esc(p.updated_at.replace('T',' '))}</td><td class="row-actions"><button data-action="open" data-id="${p.id}">打开</button>${p.status==='draft'?`<button data-action="release" data-id="${p.id}">正式发布</button>`:''}${p.status==='released'?`<button data-action="void" data-id="${p.id}">作废</button>`:''}${p.status!=='released'?`<button data-action="delete" data-id="${p.id}">删除</button>`:''}</td></tr>`}).join("")||'<tr><td colspan="7" class="empty">暂无项目</td></tr>';$$('button',body).forEach(b=>b.onclick=()=>projectAction(b.dataset.action,b.dataset.id))}
async function projectAction(action,id){try{if(action==="open"){if(WorkspaceUI.dirty()&&!confirm('当前方案有未保存修改，确定放弃并打开其他方案？'))return;const p=await api(`/api/projects/${id}`);state.machine=p.machine;state.sequence=p.sequence;state.metadata=p.metadata;state.ports=p.ports||{natural4:true,natural7:true};state.selected=state.selectedBarrel=-1;state.id=p.id;state.status=p.status;state.undo=[];state.redo=[];$("#machineSelect").value=state.machine;fillTemplates();setMeta(state.metadata);$("#natural4").checked=state.ports.natural4;$("#natural7").checked=state.ports.natural7;switchView('designer');renderAll();WorkspaceUI.markClean();return}if(action==="delete"&&confirm("确认删除这个草稿？")){await api(`/api/projects/${id}`,{method:'DELETE'});toast("已删除")}if(action==="release"){const p=await api(`/api/projects/${id}`),v=await api('/api/validate',{method:'POST',body:p});let app={reason:"正式发布",code:""};if(v.difference||v.violations.length||v.barrel_warnings?.length){app=await approval(`项目存在长度差值 ${v.difference} mm、安全冲突 ${v.violations.length} 处。${esc((v.barrel_warnings||[]).join('；'))}`);if(!app)return}try{await api(`/api/projects/${id}/release`,{method:'POST',body:{reason:app.reason,confirm_code:app.code}});toast("项目已正式发布，库存已扣减")}catch(e){if(e.data?.shortages?.length){app=await approval("当前库存不足，是否强制发布？");if(!app)return;await api(`/api/projects/${id}/release`,{method:'POST',body:{reason:app.reason,confirm_code:app.code}});toast("已强制发布")}else throw e}}if(action==="void"&&confirm("确认作废？已扣库存将自动退回。")){await api(`/api/projects/${id}/void`,{method:'POST',body:{reason:"人工确认作废"}});toast("项目已作废，库存已退回")}await reloadData();renderAll()}catch(e){toast(e.message,true)}}
function switchView(name){FluentDrag.cancel();$$('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${name}`));$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===name))}
function renderComponentsPage(){const machine=$("#componentMachineFilter")?.value||"50",q=$("#componentPageSearch")?.value.toLowerCase()||"",items=DATA.components.filter(c=>c.machine===machine&&ComponentModels.matches(c,q));$("#componentsBody").innerHTML=items.map(c=>`<tr><td>${elementThumb(c)}</td><td><b>${esc(ComponentModels.model(c).label)}</b><div class="muted">${esc(ComponentModels.describe(c))}</div><div class="muted">原名：${esc(c.name)}</div></td><td>${c.type}</td><td>${c.length}</td><td>${esc(c.direction||'—')}</td><td>${c.stock==null?'未录入':c.stock}</td><td>${esc(c.note||'')}</td><td class="row-actions"><button data-edit="${c.id}">编辑</button><button data-delete-component="${c.id}" class="danger-text">删除</button></td></tr>`).join("");$$('[data-edit]').forEach(b=>b.onclick=()=>componentModal(DATA.components.find(c=>c.id===b.dataset.edit)));$$('[data-delete-component]').forEach(b=>b.onclick=()=>deleteComponent(DATA.components.find(c=>c.id===b.dataset.deleteComponent)))}
async function deleteComponent(c){if(!c||!confirm(`确认从${c.machine}机元件库删除 ${c.name}？\n历史图纸记录不会被删除。`))return;try{await api(`/api/components/${c.id}`,{method:'DELETE'});await reloadData();renderAll();toast(`已删除 ${c.name}`)}catch(e){toast(e.message,true)}}
function componentModal(c=null){const x=c||{machine:$("#componentMachineFilter")?.value||state.machine,type:"GFA",direction:"",stock:""};openModal(c?"编辑元件":"添加螺纹元件",`<div class="modal-form"><label>所属机器<select id="cmMachine"><option value="50">ZSE 50CC Pro</option><option value="60">ZSE 60CC</option></select></label><label>元件类型<select id="cmType">${["GFA","GFF","GFM","SME","KB","KBX","KS","Spacer","OTHER"].map(t=>`<option>${t}</option>`).join('')}</select></label><label class="wide">完整型号<input id="cmName" value="${esc(x.name||'')}" placeholder="如 KB5-2-60-45°-RE"></label><label>实际长度/mm<input id="cmLength" type="number" value="${x.length||''}"></label><label>导程/mm<input id="cmPitch" type="number" value="${x.pitch||''}"></label><label>片数<input id="cmDiscs" type="number" value="${x.discs||''}"></label><label>错位角/°<input id="cmAngle" type="number" value="${x.angle||''}"></label><label>方向<select id="cmDirection"><option value="">无</option><option>RE</option><option>LI</option></select></label><label>初始库存/件<input id="cmStock" type="number" value="${x.stock??''}" placeholder="可暂不录入"></label><label class="wide">备注<textarea id="cmNote">${esc(x.note||'')}</textarea></label></div>`,[{label:"取消",click:closeModal},{label:"保存",primary:true,click:async()=>{const body={id:x.id,machine:$("#cmMachine").value,type:$("#cmType").value,name:$("#cmName").value,length:+$("#cmLength").value,pitch:+$("#cmPitch").value||null,discs:+$("#cmDiscs").value||null,angle:+$("#cmAngle").value||null,direction:$("#cmDirection").value,stock:$("#cmStock").value===''?null:+$("#cmStock").value,note:$("#cmNote").value};try{await api('/api/components',{method:'POST',body});closeModal();await reloadData();renderAll();toast("元件已保存")}catch(e){toast(e.message,true)}}}]);$("#cmMachine").value=x.machine;$("#cmType").value=x.type;$("#cmDirection").value=x.direction||"";$("#cmName").onchange=()=>{const name=$("#cmName").value,nums=(name.match(/\d+/g)||[]).map(Number),type=typeOf(name);$("#cmType").value=type;$("#cmLength").value=parseLength(name)||'';if(['GFA','GFF','GFM','SME'].includes(type)&&nums.length>=3)$("#cmPitch").value=nums.at(-2);if(['KB','KBX'].includes(type)&&nums.length>=4){$("#cmDiscs").value=nums[0];$("#cmAngle").value=nums.at(-1)}$("#cmDirection").value=/-LI?$/i.test(name)?'LI':/-RE$/i.test(name)?'RE':''}}
function showModelDetails(c){const m=ComponentModels.model(c),refs=(DATA.templates||[]).filter(t=>t.machine===c.machine&&t.sequence.includes(c.name)).slice(0,3);openModal(m.label,`<div class="model-detail-preview">${ComponentModels.symbol(c,DATA.machines[c.machine||state.machine],{id:'detail-'+c.id,layout:'class="element-thumb"'})}</div>${MachineDimensions.libraryNote(c.machine||state.machine)}<dl class="model-details"><dt>原始型号（保存时不变）</dt><dd>${esc(c.name)}</dd><dt>所属机器</dt><dd>${esc(DATA.machines[c.machine||state.machine].name)}</dd><dt>类型</dt><dd>${m.type==='KB'?'KB 捏合／剪切块':esc(m.type)}</dd><dt>长度</dt><dd>${m.length} mm</dd>${m.discs!=null?`<dt>片数</dt><dd>${m.discs}片${m.type==='KB'?`（单片厚度 ${(m.length/m.discs).toFixed(2)} mm）`:''}</dd>`:''}${m.lobes!=null?`<dt>头数／叶数</dt><dd>${m.lobes}（不代表螺杆根数）</dd>`:''}${m.pitch!=null?`<dt>导程</dt><dd>${m.pitch} mm</dd>`:''}${m.angle!=null?`<dt>错位角</dt><dd>${m.angle}°（相邻捏合片）</dd>`:''}<dt>方向标记</dt><dd>${m.direction||'原型号未标注'}${m.angle===90?'；90°属中性错位角':m.direction==='LI'?' · 反向':m.direction==='RE'?' · 正向':''}</dd></dl>${m.mismatches.length?`<p class="warn-box">库参数与型号有差异，需核对：${esc(m.mismatches.join('；'))}</p>`:''}<p class="muted">Machine图标及此详情图按完整型号生成矢量工程示意，外形待图纸终核，非制造CAD。KS仅示意长度与单片轮廓，不推测A/E、M后缀的端面加工形状。元件库保留曲线外形；组合图及导出安装图使用平齐装配示意。两种显示共用型号参数，不改变长度、旋向和KB错位角；原始PDF/Excel不覆盖。保存仍使用原始型号，不合并库存或历史记录。</p><div class="muted model-provenance"><b>历史出处（导入记录）</b>${refs.length?refs.map(t=>`<p>${esc(t.name)}<br>${esc(t.source||'')}</p>`).join(''):'<p>暂无历史出处，需核对供应商图纸。</p>'}<a href="/manual-review/index.html?v=1.16" target="_blank" rel="noopener">查看完整型号、PDF文字出处与图形审核</a></div>`,[{label:'关闭',primary:true,click:closeModal}])}
function selectedComponentInfo(){if(state.selected<0){toast('请先选择螺纹元件',true);return}const c=comp(state.sequence[state.selected]),span=calculate().spans[state.selected];openModal(c.name,`<div class="info-grid"><b>序号</b><span>${state.selected+1}</span><b>类型</b><span>${c.type}</span><b>长度</b><span>${c.length} mm</span><b>轴向范围</b><span>${displayPosition(span.start)}～${displayPosition(span.end)} mm</span><b>导程</b><span>${c.pitch??'—'}</span><b>片数</b><span>${c.discs??'—'}</span><b>错位角</b><span>${c.angle!=null?c.angle+'°':'—'}</span><b>方向</b><span>${c.direction||'—'}</span></div>`,[{label:'从螺杆删除',click:()=>{closeModal();removeElementByName(c.name)}},{label:'关闭',primary:true,click:closeModal}])}
function showComponentInfo(name){const c=comp(name),engineering=[c.pitch!=null?`导程 ${c.pitch} mm`:'',c.discs!=null?`${c.discs}片`:'',c.angle!=null?`错位角 ${c.angle}°`:'',c.direction?`方向 ${c.direction}`:''].filter(Boolean).join(' · ');$("#selectedInfo").innerHTML=`<b>${esc(c.name)}</b><p>所属：${DATA.machines[c.machine]?.name}<br>类型：${c.type}　长度：${c.length} mm<br>${engineering?engineering+'<br>':''}库存：${c.stock==null?'未录入':c.stock+' 件'}</p><button onclick="addElement('${String(name).replaceAll("'","\\'")}')">添加到组合</button>`}
function renderInventory(){const machine=$("#inventoryMachine")?.value||"50",q=$("#inventorySearch")?.value.toLowerCase()||"",items=DATA.components.filter(c=>c.machine===machine&&c.name.toLowerCase().includes(q));$("#inventoryBody").innerHTML=items.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${c.type}</td><td>${c.length} mm</td><td>${c.stock==null?'未录入':c.stock}</td><td>${c.stock==null?'—':Math.floor(c.stock/2)}</td><td><span class="badge ${c.stock==null?'warn':c.stock<=2?'bad':'ok'}">${c.stock==null?'待盘点':c.stock<=2?'库存低':'正常'}</span></td><td><button data-stock="${c.id}">盘点/调整</button></td></tr>`).join("");$$('[data-stock]').forEach(b=>b.onclick=()=>stockModal(DATA.components.find(c=>c.id===b.dataset.stock)))}
function stockModal(c){openModal("库存盘点 / 调整",`<p><b>${esc(c.name)}</b></p><div class="modal-form"><label>调整方式<select id="stockMode"><option value="set">盘点后设为</option><option value="add">增加/减少</option></select></label><label>数量/件<input id="stockQty" type="number" value="${c.stock??0}"></label><label class="wide">原因<input id="stockReason" value="人工盘点"></label></div>`,[{label:"取消",click:closeModal},{label:"确认",primary:true,click:async()=>{try{await api('/api/inventory/adjust',{method:'POST',body:{component_id:c.id,mode:$("#stockMode").value,quantity:+$("#stockQty").value,reason:$("#stockReason").value}});closeModal();await reloadData();renderAll();toast("库存已更新")}catch(e){toast(e.message,true)}}}])}
async function showInventoryHistory(){try{const xs=await api('/api/inventory/history');openModal("库存出入库记录",`<div class="table-wrap" style="max-height:55vh"><table><thead><tr><th>时间</th><th>机器</th><th>型号</th><th>变动</th><th>原因</th></tr></thead><tbody>${xs.map(x=>`<tr><td>${esc(x.created_at.replace('T',' '))}</td><td>${x.machine}</td><td>${esc(x.name)}</td><td style="color:${x.delta>=0?'green':'red'}">${x.delta>0?'+':''}${x.delta}</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div>`,[{label:"关闭",click:closeModal}])}catch(e){toast(e.message,true)}}
function renderSettings(){$("#codeHint").textContent=DATA.settings.confirm_hint||"尾号0731";$("#machineSpecs").innerHTML=Object.values(DATA.machines).map(s=>`<p><b>${s.name}</b><br>12 × ${s.section_length} mm｜机筒坐标 ${s.barrel_length} mm｜元件总长 ${s.element_length} mm｜机型直径规格 ${s.diameter} mm（非单块实测值）<br>实际螺杆外径／机筒内径及配合间隙须按图纸核对，不跨机型使用模块。</p>`).join('')}
async function handleImport(file){if(!file)return;const reader=new FileReader();reader.onload=async()=>{try{const x=await api('/api/import',{method:'POST',body:{filename:file.name,data:reader.result}});openModal("旧图纸识别预览",`<p>文件：<b>${esc(file.name)}</b><br>识别机器：${esc(DATA.machines[x.machine]?.name)}<br>识别元件：${x.sequence.length}个</p>${x.warnings?.map(w=>`<div class="warn-box">${esc(w)}</div>`).join('')||''}<div class="import-preview"><table><thead><tr><th>序号</th><th>型号</th><th>长度</th></tr></thead><tbody>${x.sequence.map((n,i)=>`<tr><td>${i+1}</td><td>${esc(n)}</td><td>${parseLength(n)}</td></tr>`).join('')}</tbody></table></div><p class="muted">导入后请检查型号、顺序和总长度，再正式保存。</p>`,[{label:"取消",click:closeModal},{label:"确认导入",primary:true,click:()=>applyImport(x)}])}catch(e){toast(e.message,true)}};reader.readAsDataURL(file)}
async function applyImport(x){try{for(const name of x.sequence){if(!DATA.components.some(c=>c.machine===x.machine&&c.name===name))await api('/api/components',{method:'POST',body:{machine:x.machine,name,type:typeOf(name),length:parseLength(name),note:`从${x.filename}自动导入`}})}await reloadData();state.machine=x.machine;state.sequence=x.sequence;state.metadata={...x.metadata,machine_no:DATA.machines[x.machine].machine_no,date:today(),version:"导入",side1_label:"阻燃剂",side2_label:"玻纤"};state.ports=x.ports||{natural4:true,natural7:true};state.id=null;state.status="draft";state.undo=[];state.redo=[];state.selected=state.selectedBarrel=-1;$("#machineSelect").value=state.machine;fillTemplates();setMeta(state.metadata);$("#natural4").checked=state.ports.natural4??true;$("#natural7").checked=state.ports.natural7??true;closeModal();switchView('designer');renderAll();toast("导入完成，请核对后保存")}catch(e){toast(e.message,true)}}
function projectPayload(){collectMeta();return {project:{id:state.id,machine:state.machine,status:state.status,metadata:cleanMetadata(),ports:state.ports,sequence:state.sequence,exported_at:new Date().toISOString()}}}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportJSON(){downloadBlob(new Blob([JSON.stringify(projectPayload(),null,2)],{type:'application/json'}),(state.metadata.drawing_name||'螺杆组合')+'.json')}
async function exportXlsx(){try{const r=await fetch('/api/export/xlsx',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':DATA.auth?.csrf||''},body:JSON.stringify(projectPayload())});if(!r.ok){const e=await r.json();throw Error(e.error)}downloadBlob(await r.blob(),(state.metadata.drawing_name||'螺杆组合')+'.xlsx')}catch(e){toast(e.message,true)}}
async function embedSvgAssets(svg){const urls=[...new Set([...svg.matchAll(/href="(https?:[^\"]+)"/g)].map(m=>m[1]))];for(const url of urls){const blob=await fetch(url).then(r=>r.blob()),data=await new Promise(ok=>{const fr=new FileReader();fr.onload=()=>ok(fr.result);fr.readAsDataURL(blob)});svg=svg.replaceAll(url,data)}return svg}
async function exportPNG(){try{renderReport();const svg=await embedSvgAssets($('#printRoot .reference-page > svg').outerHTML),blob=new Blob([svg],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=2400;const box=new DOMParser().parseFromString(svg,'image/svg+xml').documentElement.viewBox.baseVal;c.height=Math.round(c.width*box.height/box.width);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);c.toBlob(b=>downloadBlob(b,(state.metadata.drawing_name||'螺杆组合')+'.png'))};img.src=url}catch(e){toast('PNG导出失败：'+e.message,true)}}
