function renderReportLegacy(){collectMeta();const v=calculate(),s=spec(),m=state.metadata,bom=[...new Set(state.sequence)].map(name=>{const c=comp(name),sets=state.sequence.filter(n=>n===name).length,pieces=sets*2,short=c.stock==null?null:Math.max(0,pieces-c.stock);return {...c,sets,pieces,short}}).sort((a,b)=>a.type.localeCompare(b.type)||a.name.localeCompare(b.name));let pos=-s.entry_offset;const rows=state.sequence.map((name,i)=>{const c=comp(name);pos+=c.length;return {i:i+1,pos,name,len:c.length,bad:v.violations.some(x=>x.index===i)}}),half=Math.ceil(rows.length/2),table=part=>`<table class="print-table"><thead><tr><th>No.</th><th>mm</th><th>型号 / Name</th><th>长度</th></tr></thead><tbody>${part.map(r=>`<tr ${r.bad?'style="color:#c22;background:#fee"':''}><td>${r.i}</td><td>${Math.round(r.pos)}</td><td>${esc(r.name)}</td><td>${r.len}</td></tr>`).join('')}</tbody></table>`;const barrel=['1 FEED','2 HEAT BARRIER','3 BARREL',state.ports.natural4?'4 NATURAL VENT':'4 CLOSED','5 SIDE FEED','6 BARREL',state.ports.natural7?'7 NATURAL VENT':'7 CLOSED','8 SIDE FEED','9 BARREL','10 BARREL','11 VACUUM','12 BARREL'];
$("#printRoot").innerHTML=`<section class="print-page">${printHeader()}<div class="print-title">${esc(m.drawing_name||s.name)}</div><div class="print-meta">机器编号：${esc(m.machine_no)}　版本：${esc(m.version)}<br>日期：${esc(m.date)}　材料：${esc(m.material||'')}<br>工艺备注：${esc(m.comments||'')}</div><div class="print-drawing">${drawingSVG()}</div><div class="print-foot"><span>${s.name} · 12 × ${s.section_length} mm</span><span>第1页 / Page 1</span></div></section>
<section class="print-page">${printHeader()}<div class="print-section-title">螺纹元件需求清单 / Required screw elements</div><div class="print-info"><span>图纸：${esc(m.drawing_name)}</span><span>机器：${s.name}</span><span>材料：${esc(m.material)}</span><span>日期：${esc(m.date)}</span></div><table class="print-table" style="margin-top:3mm"><thead><tr><th>序号</th><th>元件型号</th><th>类型</th><th>长度/mm</th><th>组合位置/套</th><th>实际需要/件</th><th>当前库存/件</th><th>缺少/件</th></tr></thead><tbody>${bom.map((c,i)=>`<tr><td>${i+1}</td><td>${esc(c.name)}</td><td>${c.type}</td><td>${c.length}</td><td>${c.sets}</td><td>${c.pieces}</td><td>${c.stock==null?'未录入':c.stock}</td><td>${c.short==null?'未录入':c.short}</td></tr>`).join('')}</tbody></table><div class="print-foot" style="margin-top:3mm"><span>数量说明：1套 = 双螺杆实际单件2件</span><span>第2页 / Page 2</span></div></section>
<section class="print-page">${printHeader()}<div class="print-section-title">安装顺序与机筒配置 / Installation & barrel configuration</div><div class="print-columns">${table(rows.slice(0,half))}${table(rows.slice(half))}</div><div style="display:grid;grid-template-columns:2fr 1fr;gap:4mm;margin-top:2mm"><div class="print-mini-drawing">${drawingSVG(true)}</div><table class="print-table"><thead><tr><th>位置</th><th>机筒</th></tr></thead><tbody>${barrel.map((b,i)=>`<tr><td>${String.fromCharCode(65+i)}</td><td>${esc(b)}</td></tr>`).join('')}</tbody></table></div><div class="print-foot"><span>总长 ${v.total} / ${v.target} mm　${v.violations.length?`⚠ 非标准组合：${v.violations.length}处安全冲突`:'安全规则检查通过'}</span><span>第3页 / Page 3</span></div></section>`}
